import json,os
p='/tmp/probe/config/ty/o3/marmite.json'
if os.path.exists(p):
  c=json.load(open(p))['config']['markdown_parser'];print(json.dumps(c))
"; }
echo "--- render only empty"; show 'markdown_parser:
  render: {}
'
echo "--- render unsafe false"; show 'markdown_parser:
  render:
    unsafe: false
